/**
 * Contentful Configuration
 *
 * Values are sourced from config/default.js via getConfig(), which is evaluated
 * server-side (where process.env is available) and serialized into the bundle.
 * This means the delivery token is available client-side (it's public/read-only),
 * while the preview token is only populated when CONTENTFUL_PREVIEW_TOKEN is set
 * in the server environment.
 */
import { getConfig } from '@salesforce/pwa-kit-runtime/utils/ssr-config';

type ContentfulConfig = {
  spaceId: string;
  accessToken: string;
  environment: string;
  previewAccessToken: string;
};

export const getContentfulConfig = (): ContentfulConfig => {
  const { app } = getConfig();
  return (app as { contentful: ContentfulConfig }).contentful;
};

/**
 * SFCC ↔ Contentful mapping constants.
 *
 * Locale/site mapping (SUPPORTED_LOCALES, SITE_LOCALES) comes from
 * contentfulMapping.generated.ts — regenerate via
 * `npm run sync:regional-config`, which derives it from the same SCAPI
 * fetch that populates config/sites.generated.js. The environment ID is
 * injected per MRT tier via the CONTENTFUL_ENVIRONMENT_ID env var; this
 * file provides the canonical reference for what each tier maps to.
 *
 * Tier topology (DEV → TEST → OMS INT → STAGE → UAT → PRODUCTION):
 *   dev | test | sit | staging | uat | master (via 'production' alias)
 */

import { SITE_LOCALES as GENERATED_SITE_LOCALES, SUPPORTED_LOCALES } from './contentfulMapping.generated';

// ── Locale mapping ────────────────────────────────────────────────────────────

export { SUPPORTED_LOCALES };

export type SupportedLocale = (typeof SUPPORTED_LOCALES)[number];

/** The Contentful default locale — all others fall back to this. */
export const DEFAULT_LOCALE: SupportedLocale = 'en';

/**
 * Maps SFCC site IDs to the locale codes they serve.
 * Matches the l10n.supportedLocales configuration in config/sites.js.
 */
export const SITE_LOCALES = GENERATED_SITE_LOCALES as Record<string, readonly SupportedLocale[]>;

// ── Environment mapping ───────────────────────────────────────────────────────

/**
 * Contentful environment IDs per delivery tier.
 * These are the values set in CONTENTFUL_ENVIRONMENT_ID per MRT target.
 * Production uses the 'production' alias which points to 'master'.
 */
export const CONTENTFUL_ENVIRONMENTS = {
  dev: 'dev',
  test: 'test',
  sit: 'sit',
  staging: 'staging',
  uat: 'uat',
  production: 'master',
} as const;

export type ContentfulEnvironment = keyof typeof CONTENTFUL_ENVIRONMENTS;

// ── Content type IDs ──────────────────────────────────────────────────────────

/** Contentful content type IDs used by the app. */
export const CONTENT_TYPE_IDS = {
  shoppableImage: 'shoppableImage',
} as const;

export type ContentTypeId = (typeof CONTENT_TYPE_IDS)[keyof typeof CONTENT_TYPE_IDS];

// ── SFCC product ID field ─────────────────────────────────────────────────────

/**
 * The JSON key used for SFCC master product IDs within Contentful hotspot objects.
 * Matches the shape expected by overrides/app/components/contentful/experiences/shoppableImage.
 */
export const SFCC_PRODUCT_ID_FIELD = 'productId' as const;

